                    mainElement.innerText = newValue ? '是' : '否';
                } else if (typeof newValue === 'string') {
                    const lowerValue = newValue.toLowerCase();
                    const boolValue = lowerValue === 'true' || lowerValue === '是' || lowerValue === 'yes' || lowerValue === '真';
                    mainElement.innerText = boolValue ? '是' : '否';
                } else {
